import{_ as i,o as e,c as l,ao as n}from"./chunks/framework.DniuIMox.js";const d=JSON.parse('{"title":"Soil hydraulics algorithms","description":"","frontmatter":{},"headers":[],"relativePath":"tutorials/soil_hydraulics_algorithms.md","filePath":"tutorials/soil_hydraulics_algorithms.md","lastUpdated":null}'),s={name:"tutorials/soil_hydraulics_algorithms.md"};function t(o,a,r,p,c,h){return e(),l("div",null,[...a[0]||(a[0]=[n(`<h1 id="Soil-hydraulics-algorithms" tabindex="-1">Soil hydraulics algorithms <a class="header-anchor" href="#Soil-hydraulics-algorithms" aria-label="Permalink to &quot;Soil hydraulics algorithms {#Soil-hydraulics-algorithms}&quot;">​</a></h1><p><a href="./../manual/configuring_the_model">Configuring the model</a> emphasises that composing the simulation from swappable models makes it cheap to ask &quot;what changes if I use a different algorithm?&quot; This tutorial illustrates how this works for <a href="/Microclimate.jl/dev/api#Microclimate.CampbellSoilHydraulics"><code>CampbellSoilHydraulics</code></a>&#39;s two independent algorithm choices.</p><h2 id="Infiltration-algorithm" tabindex="-1">Infiltration algorithm <a class="header-anchor" href="#Infiltration-algorithm" aria-label="Permalink to &quot;Infiltration algorithm {#Infiltration-algorithm}&quot;">​</a></h2><p><code>infiltration_algorithm</code> selects how <a href="/Microclimate.jl/dev/manual/soil_moisture#Soil-water-mass-balance">Campbell&#39;s soil water mass balance</a> is solved: <a href="/Microclimate.jl/dev/api#Microclimate.MatricPotentialAlgorithm"><code>MatricPotentialAlgorithm</code></a> (Campbell&#39;s Program 8.1, using matric potential as the dependent variable directly — most efficient in dry soil) or <a href="/Microclimate.jl/dev/api#Microclimate.MatricFluxPotentialAlgorithm"><code>MatricFluxPotentialAlgorithm</code></a> (Program 8.2, using matric flux potential — fewer iterations, more stable in wet soil). At moderate-to-wet soil moisture the two should agree closely:</p><div class="language-@example vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">@example</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>using Microclimate, Unitful</span></span>
<span class="line"><span></span></span>
<span class="line"><span>config = MicroConfig(; soil_moisture_strategy = DynamicSoilMoisture())</span></span>
<span class="line"><span>n = length(Microclimate.DEFAULT_DEPTHS)</span></span>
<span class="line"><span>wet_initial_moisture = fill(0.30, n)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>function run_with(infiltration_algorithm)</span></span>
<span class="line"><span>    soil_hydraulic_model = example_soil_hydraulic_model(; infiltration_algorithm)</span></span>
<span class="line"><span>    solve(example_microclimate_problem(; soil_hydraulic_model, config,</span></span>
<span class="line"><span>        initial_soil_moisture = wet_initial_moisture))</span></span>
<span class="line"><span>end</span></span>
<span class="line"><span></span></span>
<span class="line"><span>psi_out = run_with(MatricPotentialAlgorithm())</span></span>
<span class="line"><span>phi_out = run_with(MatricFluxPotentialAlgorithm())</span></span>
<span class="line"><span>maximum(abs.(psi_out.soil_moisture .- phi_out.soil_moisture))</span></span></code></pre></div><p>In dry soil, <code>MatricFluxPotentialAlgorithm</code> is documented (Campbell 1985) to be less accurate — a case where the choice actually matters rather than being interchangeable.</p><h2 id="Rainfall-entry-mode" tabindex="-1">Rainfall entry mode <a class="header-anchor" href="#Rainfall-entry-mode" aria-label="Permalink to &quot;Rainfall entry mode {#Rainfall-entry-mode}&quot;">​</a></h2><p><code>rainfall_entry_mode</code> selects how rain reaches the soil column each hour: <a href="/Microclimate.jl/dev/api#Microclimate.PoolCapacityRainfall"><code>PoolCapacityRainfall</code></a> (the default — a surface pool fills the top node&#39;s own storage capacity before infiltration runs), <a href="/Microclimate.jl/dev/api#Microclimate.ImplicitFluxRainfall"><code>ImplicitFluxRainfall</code></a> (rain enters as a flux boundary condition inside the same implicit solve infiltration itself uses, alongside evaporation), or <a href="/Microclimate.jl/dev/api#Microclimate.RateLimitedFrontRainfall"><code>RateLimitedFrontRainfall</code></a> (a stateless, rate-limited multi-layer wetting-front march). Comparing them under a rainy period:</p><div class="language-@example vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">@example</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>environment_daily = example_daily_environment(; rainfall = fill(30.0, 12)u&quot;kg/m^2&quot;)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>function run_with_rain(rainfall_entry_mode)</span></span>
<span class="line"><span>    soil_hydraulic_model = example_soil_hydraulic_model(; rainfall_entry_mode)</span></span>
<span class="line"><span>    inputs_kw = (; environment_daily, initial_soil_moisture = fill(0.15, n))</span></span>
<span class="line"><span>    solve(example_microclimate_problem(; soil_hydraulic_model, config, inputs_kw...))</span></span>
<span class="line"><span>end</span></span>
<span class="line"><span></span></span>
<span class="line"><span>pool_out = run_with_rain(PoolCapacityRainfall())</span></span>
<span class="line"><span>flux_out = run_with_rain(ImplicitFluxRainfall())</span></span>
<span class="line"><span>(pool_out.soil_moisture[end, 1], flux_out.soil_moisture[end, 1])</span></span></code></pre></div><h2 id="Frozen-soil" tabindex="-1">Frozen soil <a class="header-anchor" href="#Frozen-soil" aria-label="Permalink to &quot;Frozen soil {#Frozen-soil}&quot;">​</a></h2><p>Once a layer is frozen, water is treated as unable to move through it — both through the soil matrix and through roots — so infiltration and root uptake stop at whichever depth freezing reaches, rather than continuing through ice-filled pores. See <a href="./../manual/phase_transition">Phase transition</a> for the full mechanism, and how it interacts with <a href="./../manual/snow">Snow</a>, since a snow-covered, freezing soil column is exactly where this matters.</p><h2 id="Next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#Next-steps" aria-label="Permalink to &quot;Next steps {#Next-steps}&quot;">​</a></h2><ul><li><p><a href="./../manual/soil_moisture">Soil moisture</a> — the full Campbell (1985) theory these algorithms implement.</p></li><li><p><a href="./../manual/configuring_the_model">Configuring the model</a> — the general pattern behind comparing model choices this way.</p></li></ul>`,13)])])}const u=i(s,[["render",t]]);export{d as __pageData,u as default};
